understanding='''import {mountLearning} from './learning';\nimport {type M1EditorialData,type EmpiricalTarget} from './editorial-stage';\nimport {type M1PresentationData} from './presentation-stage';\nimport {type M1AccessData} from './access-stage';\nimport {mountTheoryReader,type TheoryChapter,type TheoryGlossaryEntry,type TheoryVariable,type TheoryModule,type TheoryReference,type TheoryValidation} from './theory-reader';\nimport {type NarrativeRun} from './narrative-stage';\nimport {mountGuidedTour} from './guided-tour';\nimport {mountActiveUnderstanding} from './active-understanding-ui';\nimport {mountWorldModel} from './world-model';\nimport './world-model.css';\n\ntype Lang='ro'|'en';\ntype Mode='theory'|'mechanisms'|'world-model'|'tour'|'active';\nexport type UnderstandingTheoryData={chapters:TheoryChapter[];glossary:TheoryGlossaryEntry[];variables:TheoryVariable[];modules:TheoryModule[];references:TheoryReference[];validations:TheoryValidation[];releaseTag:string;};\nfunction route(){const raw=decodeURIComponent(location.hash.replace(/^#/,''));const parts=raw.split('/').filter(Boolean);if(parts[0]!=='understanding')return {mode:null as Mode|null,detail:undefined as string|undefined};const candidate=parts[1] as Mode|undefined;const mode:Mode=candidate&&['theory','mechanisms','world-model','tour','active'].includes(candidate)?candidate:'theory';return {mode,detail:parts[2]};}\nexport function mountUnderstanding(host:HTMLElement,lang:Lang,runs:NarrativeRun[],m1Editorial:M1EditorialData,m1Presentation:M1PresentationData,m1Access:M1AccessData,m1Targets:EmpiricalTarget[],theory:UnderstandingTheoryData,navigate:(target:string)=>void){\n const t=(ro:string,en:string)=>lang==='ro'?ro:en;const current=route();const saved=localStorage.getItem('cem-understanding-mode') as Mode|null;const knownModes:Mode[]=['theory','mechanisms','world-model','tour','active'];const mode:Mode=current.mode??(saved&&knownModes.includes(saved)?saved:'theory');\n host.innerHTML=`<section class="understanding-shell" data-understanding-mode-current="${mode}"><div class="section-heading understanding-heading"><div><p class="eyebrow">THEORY / LEARN</p><h3>${t('Aprofundare contextuală','Contextual learning')}</h3><p>${t('Conținutul de aprofundare rămâne în panoul Theory/Learn al suprafeței InfoClar.','Deep learning remains inside the Theory/Learn panel of the InfoClar surface.')}</p></div><nav class="understanding-modes" aria-label="${t('Moduri de învățare','Learning modes')}"><button type="button" data-understanding-mode="theory" aria-pressed="${mode==='theory'}">${t('Teorie','Theory')}</button><button type="button" data-understanding-mode="mechanisms" aria-pressed="${mode==='mechanisms'}">${t('Mecanisme','Mechanisms')}</button><button type="button" data-understanding-mode="world-model" aria-pressed="${mode==='world-model'}">${t('Modelul realității','World model')}</button><button type="button" data-understanding-mode="tour" aria-pressed="${mode==='tour'}">${t('Tur ghidat','Guided tour')}</button><button type="button" data-understanding-mode="active" aria-pressed="${mode==='active'}">${t('Învățare activă','Active learning')}</button></nav></div><div id="understandingContent"></div></section>`;\n const sub=host.querySelector<HTMLElement>('#understandingContent')!;const openMode=(next:Mode)=>{localStorage.setItem('cem-understanding-mode',next);const target=`#understanding/${next}`;if(location.hash===target)mountUnderstanding(host,lang,runs,m1Editorial,m1Presentation,m1Access,m1Targets,theory,navigate);else location.hash=target;};host.querySelectorAll<HTMLButtonElement>('[data-understanding-mode]').forEach(button=>button.onclick=()=>openMode(button.dataset.understandingMode as Mode));\n if(mode==='theory'){mountTheoryReader(sub,{lang,chapters:theory.chapters,glossary:theory.glossary,variables:theory.variables,modules:theory.modules,references:theory.references,validations:theory.validations,releaseTag:theory.releaseTag,navigate},current.detail).catch(error=>{sub.innerHTML=`<div class="panel"><h3>${t('Teoria nu poate fi încărcată','Theory could not be loaded')}</h3><p>${String(error)}</p></div>`;});return;}\n if(mode==='mechanisms'){mountLearning(sub,lang,runs,m1Editorial,m1Presentation,m1Access,m1Targets,navigate);if(current.detail==='access'){requestAnimationFrame(()=>requestAnimationFrame(()=>{const stage=sub.querySelector<HTMLElement>('#m1AccessStage');stage?.scrollIntoView({block:'start'});stage?.focus({preventScroll:true});}));}else if(current.detail){requestAnimationFrame(()=>sub.querySelector<HTMLButtonElement>(`[data-mechanism="${CSS.escape(current.detail!)}"]`)?.click());}return;}\n if(mode==='world-model'){mountWorldModel(sub,lang,navigate).catch(error=>{sub.innerHTML=`<div class="panel"><h3>${t('MOD.14 nu poate fi încărcat','MOD.14 could not be loaded')}</h3><p>${String(error)}</p></div>`;});return;}\n if(mode==='active'){mountActiveUnderstanding(sub,lang,current.detail,theory.chapters,m1Access,navigate).catch(error=>{sub.innerHTML=`<div class="panel"><h3>${t('Modul activ nu poate fi încărcat','Active mode could not be loaded')}</h3><p>${String(error)}</p></div>`;});return;}\n mountGuidedTour(sub,lang,current.detail,navigate);\n}\n'''
write('web/src/understanding.ts',understanding)

