new_shell=r'''function shell() {
 graph?.destroy(); graph=undefined;
 document.documentElement.lang=lang;
 app.innerHTML=`<header class="topbar infoclar-topbar"><a class="brand" href="#" aria-label="Cognitive Epistemic Model"><img class="brand-icon" src="./icon.svg" width="42" height="42" alt=""><span>Cognitive Epistemic Model</span></a><div class="top-actions"><a class="version" id="releaseVersion" href="https://github.com/LaurentiuStaicu/cognitive-epistemic-model/releases/tag/${release.release_tag}" target="_blank" rel="noopener">${release.channel} ${release.version} · ${release.model}</a><button id="language" aria-label="${tr('Schimbă limba interfeței în engleză','Switch the interface language to Romanian')}">${lang==='ro'?'EN':'RO'}</button><a href="https://github.com/LaurentiuStaicu/cognitive-epistemic-model" target="_blank" rel="noopener">GitHub ↗</a></div></header>
 <div class="workspace infoclar-workspace"><main id="suiteRoot"></main><footer><span>${tr('Model demonstrativ · coeficienți necalibrați','Demonstration model · uncalibrated coefficients')}</span><span>${tr('Calibrarea rămâne dormantă până după v1 · web-first','Calibration remains dormant until after v1 · web-first')}</span></footer></div>`;
 const suiteRoot=document.getElementById('suiteRoot')!;
 const openUnderstanding=(next:'theory'|'mechanisms'|'world-model'|'tour'|'active')=>{stop();view='learning';contextualTool=null;localStorage.setItem('cem-understanding-mode',next);const target=`#understanding/${next}`;if(location.hash===target)shell();else location.hash=target;};
 const openSuiteView=(next:'structure'|'runs'|'comparison'|'planning'|'reference'|'process')=>{stop();view=next;contextualTool=null;if(next==='reference')registryFocus='';if(location.hash.startsWith('#understanding/'))history.replaceState(null,'',location.pathname+location.search);shell();};
 const openTool=(tool:'search'|'inspector')=>{stop();view='learning';contextualTool=tool;shell();};
 mountSuiteOverview(suiteRoot,{lang,softwareVersion:release.version,modelSpecification:release.model,variableCount:variables.length,moduleCount:modules.length,referenceCount:references.length,validationCount:validationTests.length,openUnderstanding,openView:openSuiteView,openTool});
 const theoryHost=document.getElementById('suiteTheoryContext')!;
 const auxHost=document.getElementById('suiteAuxContext')!;
 const ensureSemanticTools=()=>{if(!document.getElementById('semanticSearch'))auxHost.innerHTML=`<section class="suite-semantic-tools"><div id="semanticSearch"></div><aside id="semanticInspector" class="panel" aria-labelledby="semanticInspectorTitle" tabindex="-1"></aside></section>`;};
 const remountInspector=(focus=false)=>{ensureSemanticTools();const host=document.getElementById('semanticInspector')!;mountSemanticInspector(host,{lang,id:semanticInspectorId,onSelect:id=>{semanticInspectorId=id;remountInspector(true);}});if(focus)host.focus({preventScroll:false});};
 const remountSearch=(focus=false)=>{ensureSemanticTools();const host=document.getElementById('semanticSearch')!;mountSemanticSearch(host,{lang,initialQuery:semanticSearchQuery,onQueryChange:query=>{semanticSearchQuery=query;},onSelect:id=>{semanticInspectorId=id;remountInspector(true);}});if(focus)host.querySelector<HTMLInputElement>('#semanticSearchInput')?.focus({preventScroll:false});};
 const navigateContext=(target:string)=>{stop();const [nextRaw,...parts]=target.split(':');const payload=parts.join(':');if(nextRaw==='search'){semanticSearchQuery=payload;contextualTool='search';remountSearch(true);return;}if(nextRaw==='inspect'){semanticInspectorId=payload;contextualTool='inspector';remountInspector(true);return;}const [id,time]=parts;if(!isAppView(nextRaw))throw new Error(`unknown contextual navigation target: ${target}`);const next=nextRaw;if(location.hash.startsWith('#understanding/'))history.pushState({cemView:next,cemId:id??null,cemTime:time??null},'',location.href);view=next;contextualTool=null;if(next==='reference')registryFocus=id??'';else if(id){selected=id;step=time===undefined?0:Number(time);}shell();};
 document.getElementById('language')!.onclick=()=>{stop();lang=lang==='ro'?'en':'ro';localStorage.setItem('cem.ui.language',lang);shell();};
 if(location.hash.startsWith('#understanding/'))mountUnderstanding(theoryHost,lang,runs,m1Editorial,m1Presentation,m1Access,m1Targets,{chapters:theoryIndex,glossary:theoryGlossary,variables,modules,references,validations:validationTests,releaseTag:release.release_tag},navigateContext);
 if(contextualTool==='search')remountSearch(true);else if(contextualTool==='inspector')remountInspector(true);
 if(view==='planning')mountPlanner(auxHost,planning,decisionUncertainty,workspaceStore.current(),lang,navigateContext);
 if(view==='runs')renderRuns();
 if(view==='comparison')mountComparison(auxHost,runs,lang,(id,time)=>{selected=id;step=time;view='runs';shell();});
 if(view==='structure')renderStructure();
 if(view==='process')renderProcess();
 if(view==='reference')renderReference();
}'''
main,count=re.subn(r'function shell\(\) \{.*?\n\}\nfunction content',new_shell+'\nfunction content',main,count=1,flags=re.S)
if count!=1:raise RuntimeError('could not replace main shell')
main=main.replace("function content(html:string) { document.getElementById('content')!.innerHTML=html; }","function content(html:string) { document.getElementById('suiteAuxContext')!.innerHTML=html; }")
main=main.replace("const host=document.getElementById('content')!;","const host=document.getElementById('suiteAuxContext')!;")
main=main.replace("mountVisualOdd(document.getElementById('content')!,lang,oddProcesses,subsystems);","mountVisualOdd(document.getElementById('suiteAuxContext')!,lang,oddProcesses,subsystems);")
write('web/src/main.ts',main)

package=load('web/package.json')
package['scripts']['build']=package['scripts']['build'].replace(' && npm run test:mod14 && npm run test:mod14',' && npm run test:mod14')
dump('web/package.json',package)

suite_test='''import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport {readFileSync} from 'node:fs';\nimport {calibrationExtension} from '../src/calibration-extension-contract.ts';\nconst shellSource=readFileSync(new URL('../src/suite-overview.ts',import.meta.url),'utf8');const shellCss=readFileSync(new URL('../src/suite-overview.css',import.meta.url),'utf8');const understandingSource=readFileSync(new URL('../src/understanding.ts',import.meta.url),'utf8');const mainSource=readFileSync(new URL('../src/main.ts',import.meta.url),'utf8');const indexSource=readFileSync(new URL('../index.html',import.meta.url),'utf8');\ntest('InfoClar v1.1 is the primary application shell with four common surfaces',()=>{assert.match(mainSource,/mountSuiteOverview\(suiteRoot/);assert.match(mainSource,/id="suiteRoot"/);for(const token of ['suite-model-panel','suite-theory-panel','suite-dashboard-panel','suite-aux-panel'])assert(shellSource.includes(token),token);assert.match(shellCss,/grid-template-areas:'model theory' 'dashboard aux'/);assert.match(shellCss,/@media\(max-width:760px\)[\\s\\S]*grid-template-areas:'model' 'theory' 'dashboard' 'aux'/);});\ntest('legacy permanent chrome is absent and supporting functions are contextual',()=>{for(const forbidden of ['navigation-shell','data-nav-group','semantic-inspector-global','class="intro"'])assert.equal(mainSource.includes(forbidden),false,forbidden);assert.match(shellSource,/id="suiteTheoryContext"/);assert.match(shellSource,/id="suiteAuxContext"/);assert.match(shellSource,/data-suite-tool="search"/);assert.match(shellSource,/data-suite-tool="inspector"/);assert.match(mainSource,/ensureSemanticTools/);});\ntest('cognitive visualization stays model-specific and MOD.14 is first-class',()=>{for(const token of ['Nexp','F','C','B','W','Aissue','Pprior','LR','Pwm','Uwm','Share','EngageIntent','Access'])assert(shellSource.includes(token),token);assert.match(shellSource,/cem-mechanism-map/);assert.match(shellSource,/data-suite-learn="world-model"/);});\ntest('Theory Learn is contextual rather than an overview sub-application',()=>{assert.match(understandingSource,/type Mode='theory'\\|'mechanisms'\\|'world-model'\\|'tour'\\|'active'/);assert.equal(understandingSource.includes("'overview'"),false);assert.equal(understandingSource.includes('mountSuiteOverview'),false);assert.match(understandingSource,/Contextual learning|Aprofundare contextuală/);});\ntest('English is first-run default and bilingual choice persists locally',()=>{assert.match(indexSource,/<html lang="en">/);assert.match(mainSource,/cem\\.ui\\.language/);assert.match(mainSource,/savedLanguage==='ro'\\|\\|savedLanguage==='en'\\?savedLanguage:'en'/);assert.match(mainSource,/localStorage\\.setItem\\('cem\\.ui\\.language',lang\\)/);});\ntest('calibration stays dormant post-v1 without Advanced mode',()=>{assert.equal(calibrationExtension.status,'PLANNED_POST_V1');assert.equal(calibrationExtension.mounted,false);assert.equal(calibrationExtension.uploadControlAvailable,false);assert.deepEqual([...calibrationExtension.acceptedExtensions],['.txt','.md','.csv','.tsv','.json','.xlsx','.ods']);assert(!mainSource.includes("./calibration-extension-contract"));assert(!shellSource.includes('type="file"'));assert(!shellSource.toLowerCase().includes('advanced mode'));assert.match(shellSource,/Web-first|web-first/);assert.match(shellSource,/Flatpak/);});\n'''
write('web/tests/suite-standard.test.ts',suite_test)

smoke=read('web/scripts/smoke.mjs')
smoke=smoke.replace(" const domainForView={learning:'understand',structure:'understand',process:'understand',runs:'analyze',comparison:'analyze',planning:'act',reference:'library'};\n const openView=async view=>{\n  const domain=domainForView[view];\n  assert(domain,`missing IA domain for view ${view}`);\n  await page.locator(`[data-nav-group=\"${domain}\"]`).click();\n  await page.locator(`[data-view=\"${view}\"]`).click();\n };"," const openView=async view=>{\n  if(view==='learning'){await page.locator('[data-suite-learn=\"mechanisms\"]').first().click();return;}\n  await page.locator(`[data-suite-view=\"${view}\"]`).first().click();\n };")
pattern=r''' assert\.equal\(await page\.locator\('search\.global-search'\)\.count\(\),1\);.*? await page\.locator\('\[data-nav-group="understand"\]'\)\.click\(\);\n await waitTheory\(\);'''
replacement=''' assert.equal(await page.locator('.navigation-shell').count(),0);\n assert.equal(await page.locator('#semanticSearchInput').count(),0);\n assert.equal(await page.locator('#semanticInspector').count(),0);\n await page.locator('[data-suite-tool="search"]').click();\n assert.equal(await page.locator('#semanticSearchInput').getAttribute('type'),'search');\n assert.equal(await page.locator('label[for="semanticSearchInput"]').count(),1);\n assert.equal(await page.locator('[role="combobox"],[role="listbox"],[role="option"]').count(),0);\n await page.locator('#semanticSearchInput').fill('familiaritate');\n await page.locator('#semanticSearchForm button[type="submit"]').click();\n await page.locator('[data-search-result-id="VAR.FAMILIARITY.CLAIM"]').waitFor();\n assert.match(await page.locator('#semanticSearchSummary').textContent(),/rezultate semantice/);\n await page.locator('[data-search-result-id="VAR.FAMILIARITY.CLAIM"] [data-search-inspect-id]').click();\n assert.equal(await page.locator('aside#semanticInspector').count(),1);\n assert.equal(await page.locator('#semanticInspector').getAttribute('data-inspector-kind'),'entity');\n assert.equal(await page.locator('#semanticInspector').getAttribute('data-inspector-id'),'VAR.FAMILIARITY.CLAIM');\n assert.match(await page.locator('#semanticInspector').textContent(),/VAR\\.FAMILIARITY\\.CLAIM/);\n const searchValueBeforeContext=await page.locator('#semanticSearchInput').inputValue();\n await openView('runs');\n await page.locator('#scenario').waitFor();\n assert.equal(await page.locator('#semanticSearchInput').count(),0);\n await page.locator('[data-suite-tool="search"]').click();\n assert.equal(await page.locator('#semanticSearchInput').inputValue(),searchValueBeforeContext);\n await page.locator('[data-suite-learn="theory"]').click();\n await waitTheory();'''
smoke,n=re.subn(pattern,replacement,smoke,count=1,flags=re.S)
if n!=1:raise RuntimeError('smoke search/navigation block not replaced')
pattern2=r''' const domainBox=await page\.locator\('\[data-nav-group="understand"\]'\)\.boundingBox\(\);.*? assert\.equal\(await page\.locator\('\[data-understanding-mode\]'\)\.count\(\),6\);'''
replacement2=''' const theoryButton=page.locator('[data-suite-learn="theory"]').first();\n const domainBox=await theoryButton.boundingBox();\n assert(domainBox&&domainBox.height>=44,'Theory/Learn target must remain at least 44px high');\n await theoryButton.focus();\n assert(Number.parseFloat(await theoryButton.evaluate(el=>getComputedStyle(el).outlineWidth))>=3,'visible focus ring must be at least 3px');\n assert.equal(await page.locator('[data-nav-group]').count(),0);\n assert.equal(await page.locator('.navigation-shell').count(),0);\n assert.equal(await page.locator('.suite-model-panel').count(),1);\n assert.equal(await page.locator('.suite-theory-panel').count(),1);\n assert.equal(await page.locator('.suite-dashboard-panel').count(),1);\n assert.equal(await page.locator('.suite-aux-panel').count(),1);\n await openView('runs');await page.locator('#scenario').waitFor();\n await openView('planning');await page.locator('#bestBundle').waitFor();\n await openView('reference');await page.locator('[data-registry-id]').first().waitFor();\n await page.locator('[data-suite-learn="theory"]').click();await waitTheory();\n assert.equal(await page.locator('[data-understanding-mode]').count(),5);'''
smoke,n=re.subn(pattern2,replacement2,smoke,count=1,flags=re.S)
if n!=1:raise RuntimeError('smoke IA block not replaced')
write('web/scripts/smoke.mjs',smoke)

# Guardrails: the permanent chrome must not regress to the retired architecture.
main_check=read('web/src/main.ts')
for forbidden in ('navigation-shell','data-nav-group','semantic-inspector-global','<div class="intro">'):
    if forbidden in main_check:
        raise RuntimeError(f'legacy permanent chrome remains: {forbidden}')
